import * as T from './three.module.js';
import {GROUPS,FIELDS,DEFAULTS,NONE,STORAGE_KEY,normalize,timing} from './impact-settings.mjs';
const $=id=>document.getElementById(id);
let settings={...DEFAULTS},playing=true,time=0,soundEnabled=false,audio=null,last=performance.now(),lastSoundCycle=-1,cycle=0;
try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){settings=normalize(JSON.parse(raw));$('preset').value='custom';}$('saveStatus').textContent='브라우저에 자동 저장';}catch{$('saveStatus').textContent='설정을 읽지 못해 기본값을 열었습니다.';}
const display=(v,unit)=>`${Number(v.toFixed(2))}${unit?' '+unit:''}`;
for(const group of GROUPS){const box=document.createElement('details');box.className='group';box.open=true;const summary=document.createElement('summary');summary.textContent=group.title;const desc=document.createElement('p');desc.textContent=group.description;summary.append(desc);box.append(summary);const fields=document.createElement('div');fields.className='fields';for(const [key,label,min,max,step,,unit,hint] of group.fields){const wrap=document.createElement('label');wrap.className='field';wrap.htmlFor=key;const heading=document.createElement('span');heading.className='field-head';const title=document.createElement('span');title.textContent=label;const output=document.createElement('output');output.id=key+'Value';output.htmlFor=key;heading.append(title,output);const input=document.createElement('input');Object.assign(input,{type:'range',id:key,min,max,step,value:settings[key]});const small=document.createElement('small');small.id=key+'Hint';small.textContent=hint;input.setAttribute('aria-describedby',small.id);input.addEventListener('input',()=>{settings[key]=Number(input.value);$('preset').value='custom';sync();save();});wrap.append(heading,input,small);fields.append(wrap);}box.append(fields);$('controls').append(box);}
function sync(){for(const [key,,,,,,unit] of FIELDS){$(key).value=settings[key];$(key+'Value').textContent=display(settings[key],unit);}time=Math.min(time,timing(settings).end);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(settings));$('saveStatus').textContent='브라우저에 저장됨';}catch{$('saveStatus').textContent='저장하지 못했습니다. 설정 파일로 보관하세요.';}}
function restart(){time=0;cycle++;lastSoundCycle=-1;playing=true;updatePlay();}
function updatePlay(){$('play').textContent=playing?'일시정지':'재생';}
$('play').onclick=()=>{playing=!playing;updatePlay();};$('replay').onclick=restart;
$('scrub').oninput=()=>{playing=false;time=Number($('scrub').value)*timing(settings).end;updatePlay();};
$('preset').onchange=()=>{const p=$('preset').value;if(p==='custom')return;settings=normalize(p==='none'?NONE:p==='heavy'?{...DEFAULTS,anticipation:420,windup:28,recoil:.4,stretch:2.3,trail:1,flash:110,squash:.4,knockback:.85,particles:36,shake:.12,freeze:110,volume:55}:DEFAULTS);sync();save();restart();};
$('reset').onclick=()=>{settings={...DEFAULTS};$('preset').value='default';sync();save();restart();};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,settings},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='타격감-설정.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('sound').onclick=async()=>{try{if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();await audio.resume();soundEnabled=!soundEnabled;$('sound').textContent=soundEnabled?'소리 끄기':'소리 켜기';$('sound').setAttribute('aria-pressed',String(soundEnabled));}catch{$('sound').textContent='소리를 사용할 수 없습니다';}};
function playHit(){if(!soundEnabled||!audio||settings.volume===0)return;const oscillator=audio.createOscillator(),gain=audio.createGain(),now=audio.currentTime;oscillator.type='triangle';oscillator.frequency.setValueAtTime(180,now);oscillator.frequency.exponentialRampToValueAtTime(45,now+.09);gain.gain.setValueAtTime(settings.volume/100*.35,now);gain.gain.exponentialRampToValueAtTime(.001,now+.13);oscillator.connect(gain).connect(audio.destination);oscillator.start(now);oscillator.stop(now+.14);}
sync();
const scene=new T.Scene();scene.add(new T.HemisphereLight(0xcfe7ff,0x263650,2.5));const light=new T.DirectionalLight(0xffe4bd,3);light.position.set(-3,8,5);scene.add(light);
let renderer;try{renderer=new T.WebGLRenderer({canvas:$('scene'),alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);}catch{$('canvasError').hidden=false;}
const camera=new T.PerspectiveCamera(36,1,.1,80),origin=new T.Vector3(2.5,3.4,7),target=new T.Vector3(0,.7,0);
const solid=color=>new T.MeshStandardMaterial({color,roughness:.55});
function mesh(geometry,material,parent,x=0,y=0,z=0){const m=new T.Mesh(geometry,material);m.position.set(x,y,z);parent.add(m);return m;}
function actor(color){const root=new T.Group(),body=new T.Group();root.add(body);const materials=[solid(color),solid(0xffd5ad),solid(color)];mesh(new T.CapsuleGeometry(.28,.42,5,12),materials[0],body,0,.73);mesh(new T.SphereGeometry(.22,16,12),materials[1],body,0,1.32);mesh(new T.ConeGeometry(.32,.52,12),materials[2],body,0,1.72);const arm=new T.Group();arm.position.set(.18,1.02,0);body.add(arm);mesh(new T.CapsuleGeometry(.085,.38,4,8),materials[0],arm,.12,-.14,0);for(const x of [-.16,.16])mesh(new T.CapsuleGeometry(.095,.22,4,8),materials[0],body,x,.25,0);return {root,body,arm,materials,colors:materials.map(m=>m.color.clone())};}
const views=[];
for(let row=0;row<2;row++){const group=new T.Group();scene.add(group);const grid=new T.GridHelper(9,18,0x3a4c64,0x24344b);group.add(grid);const a=actor(0xe9a254),b=actor(0x9780e8);a.root.position.x=-2;b.root.position.x=2;group.add(a.root,b.root);const ball=mesh(new T.SphereGeometry(.14,16,12),new T.MeshBasicMaterial({color:0xffe0a0}),group);const trail=[];for(let i=0;i<12;i++)trail.push(mesh(new T.SphereGeometry(.12,8,6),new T.MeshBasicMaterial({color:0xffab4d,transparent:true,opacity:.5}),group));const particles=[];for(let i=0;i<60;i++)particles.push(mesh(new T.OctahedronGeometry(.045),new T.MeshBasicMaterial({color:i%3?0xffca68:0xfff4d7,transparent:true}),group));const c=document.createElement('canvas');c.width=128;c.height=64;const ctx=c.getContext('2d');ctx.font='bold 40px system-ui';ctx.fillStyle='#fff0b6';ctx.textAlign='center';ctx.fillText('28',64,46);const number=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),transparent:true,depthTest:false}));number.scale.set(.65,.325,1);group.add(number);views.push({group,a,b,ball,trail,particles,number});}
const clamp=(v)=>Math.max(0,Math.min(1,v));
function drawView(v,s,t,hitAt,releaseAt){const frozen=s.freeze/1000,age=t<hitAt?t:t< hitAt+frozen?hitAt:t-frozen,impact=age-hitAt;
 const prep=releaseAt>0&&age<releaseAt?Math.sin(clamp(age/releaseAt)*Math.PI/2):0,post=Math.max(0,age-releaseAt),follow=age>=releaseAt?Math.max(0,1-post/Math.max(.001,s.follow/1000)):0;
 v.a.root.position.x=-2-follow*s.recoil;v.a.body.rotation.z=prep*s.windup*Math.PI/180-follow*.12;v.a.arm.rotation.z=-(prep*.8+follow*1.2);v.b.root.position.x=2;v.b.body.scale.set(1,1,1);v.b.body.rotation.z=0;
 for(let i=0;i<v.b.materials.length;i++)v.b.materials[i].color.copy(v.b.colors[i]);
 if(impact>=0){const response=Math.sin(clamp(impact/Math.max(.001,s.recovery/1000))*Math.PI),squash=(1-clamp(impact/.3))*s.squash;v.b.root.position.x=2+s.knockback*response;v.b.body.scale.set(1+squash,1-squash,1+squash*.4);v.b.body.rotation.z=-response*s.knockback*.22;if(impact<s.flash/1000)for(const mat of v.b.materials)mat.color.set(0xffffff);}
 const flight=clamp((age-releaseAt)/.55);v.ball.visible=age>=releaseAt&&age<hitAt;v.ball.position.set(-1.6+3.6*flight,1+Math.sin(flight*Math.PI)*s.arc,0);v.ball.scale.set(s.stretch,1/Math.sqrt(s.stretch),1/Math.sqrt(s.stretch));
 v.trail.forEach((p,i)=>{const delayed=flight-(i+1)*s.trail/45;const tailAfter=impact>=0&&impact<.14*(1-i/12)&&s.trail>0;p.visible=s.trail>0&&age>=releaseAt&&delayed>=0&&(v.ball.visible||tailAfter);p.position.set(-1.6+3.6*delayed,1+Math.sin(clamp(delayed)*Math.PI)*s.arc,0);p.scale.setScalar((1-i/12)*.8);p.material.opacity=(1-i/12)*.6;});
 v.particles.forEach((p,i)=>{p.visible=i<s.particles&&impact>=0&&impact<.65;if(!p.visible)return;const angle=((i*.61803398875)%1-.5)*2*s.spread*Math.PI/180,speed=1.2+(i*7%13)/5;p.position.set(2+Math.cos(angle)*speed*impact,1+Math.sin(angle)*speed*impact-s.gravity*impact*impact/2,Math.sin(i*2.4)*impact*.6);p.rotation.set(impact*6+i,impact*3,0);p.material.opacity=1-impact/.65;});
 v.number.visible=impact>=0&&impact<1;v.number.position.set(v.b.root.position.x+Math.sin(impact*Math.PI/2)*s.numberArc,1.9+impact*1.5-impact*impact*1.2,0);v.number.material.opacity=1-clamp(impact);
 return impact;
}
let width=0,height=0;
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;if(!renderer)return;const schedule=timing(settings);if(playing){time+=dt*Number($('speed').value);if(time>schedule.end){time=0;cycle++;}}
 const stage=$('stage'),w=stage.clientWidth,h=stage.clientHeight;if(w!==width||h!==height){width=w;height=h;renderer.setSize(w,h,false);}
 const compare=$('compare').checked;$('baselineLabel').hidden=!compare;$('tunedLabel').style.top=compare?'52%':'16px';
 $('scrub').value=time/schedule.end;$('timeLabel').textContent=time.toFixed(2)+'초';$('phase').textContent=time<schedule.release?'준비':time<schedule.hit?'발사':time<schedule.hit+settings.freeze/1000?'순간 멈춤':'피격 · 회복';
 if(playing&&time>=schedule.hit&&lastSoundCycle!==cycle){playHit();lastSoundCycle=cycle;}
 renderer.setScissorTest(true);const count=compare?2:1;for(let i=0;i<count;i++){const tuned=!compare||i===1,view=views[tuned?1:0],s=tuned?settings:NONE;for(const v of views)v.group.visible=v===view;const impact=drawView(view,s,time,schedule.hit,schedule.release);const hh=compare?Math.floor(h/2):h,y=compare&&i===0?h-hh:0;renderer.setViewport(0,y,w,hh);renderer.setScissor(0,y,w,hh);camera.aspect=w/hh;camera.position.copy(origin);const shake=impact>=0&&impact<.25?s.shake*(1-impact/.25):0;camera.position.x+=Math.sin(time*127)*shake;camera.position.y+=Math.cos(time*101)*shake;camera.lookAt(target);camera.updateProjectionMatrix();renderer.render(scene,camera);}}
requestAnimationFrame(frame);
